// @ts-nocheck
// v0.9 화면 렌더링 계층(레거시 이관). 판정 로직은 src/diagnosis(Rule Engine)만 사용한다.
// Phase 1 원칙: 화면 문구·흐름은 v0.9 그대로, 점수는 엔진 결과만 표시.
import {
  evaluate, activeQuestions, deepQuestions, profile as engineProfile, evidenceLevel,
  band as engineBand, nextTrlGate, ANCHORS, EVIDENCE, CORE,
} from '../diagnosis';
import { strategicOptions as engineStrategicOptions, riskItems as engineRiskItems } from '../diagnosis/strategy';
import { roadmapCandidates as engineRoadmapCandidates, otherFieldCandidates, loadRoadmapIndex, ROADMAP_GROUPS } from '../roadmap/candidates';
import options from './options.json';
import { versionLabel } from '../build-info';
import { buildReportViewModel, ISSUER, reportId as vmReportId } from '../reports/report-model';

const { STEPS, BUSINESS_TYPES, STAGES, SIZES, YEARS } = options;
const fmtScore = (v) => (v === null || v === undefined ? '판단 보류' : `${Math.round(v)}/100`);
const capText = (v) => (v === null || v === undefined ? '판단 보류(응답 부족)' : `${engineBand(v)}(${Math.round(v)}/100)`);
const STORAGE_KEY="beconic_tgn_v09";
function fresh(){return {step:0,visited:[0],mode:"quick",entry:"no-data",company:{name:"",stage:"소기업",roadmapField:"AI",bizType:"AI/SW 중심",sectorDetail:"",size:"1~9명",years:"1~3년",techKnow:"부분적으로 알고 있음",product:"",customer:""},discovery:{hardPart:"",automated:"",data:"",external:"",people:"",validation:""},inventory:[],answers:{},evidence:{},results:null}}
let state=fresh();
const $=id=>document.getElementById(id);
const esc=s=>String(s??"").replace(/[&<>"']/g,m=>({"&":"&amp;","<":"&lt;",">":"&gt;","\"":"&quot;","'":"&#39;"}[m]));
const cname=c=>({tech:"기술성숙",rd:"R&D 역량",exec:"실행준비",evidence:"기술기록",scale:"확장준비",strategy:"전략정렬",risk:"리스크 대응"})[c]||c;
const profile=()=>engineProfile(state.company.bizType);
const deepQs=()=>deepQuestions(state.company.bizType);
const activeQs=()=>activeQuestions(state.mode,state.company.bizType);
function roadmapSelect(){return `<select id="roadmapField">${Object.entries(ROADMAP_GROUPS).map(([g,a])=>`<optgroup label="${g}">${a.map(x=>`<option ${x===state.company.roadmapField?"selected":""}>${x}</option>`).join("")}</optgroup>`).join("")}</select>`}
function seedInv(){if(state.inventory.length)return;let p=profile(),x=p==="제조"||p==="융합"?[["제품 설계·사양","설계기술"],["핵심 생산·공정","공정기술"],["품질검사·판정","품질기술"],["설비·장비/제어","생산기술"]]:p==="딥테크"?[["핵심 원리·원천기술","원천기술"],["시제품·실험 시스템","실증기술"],["핵심 소재·부품/알고리즘","핵심기술"],["Scale-up·적용기술","응용기술"]]:p==="서비스"?[["핵심 서비스 제공방식","서비스기술"],["운영 프로세스","운영기술"],["데이터 활용","데이터기술"],["외부 플랫폼 연계","통합기술"]]:[["제품/서비스 구현","응용기술"],["데이터 활용","데이터기술"],["AI·알고리즘/노하우","핵심기술"],["외부 솔루션 연계","통합기술"]];state.inventory=x.map((a,n)=>({id:n+1,name:a[0],type:a[1],ownership:"확인필요",status:"추정",critical:n<2,trl:0,confirmed:false}))}
function syncBasic(){if(!$("companyName"))return;state.company={name:$("companyName").value.trim(),stage:$("companyStage").value,roadmapField:$("roadmapField").value,bizType:$("bizType").value,sectorDetail:$("sectorDetail").value.trim(),size:$("companySize").value,years:$("companyYears").value,techKnow:$("techKnow").value,product:$("product").value.trim(),customer:$("customer").value.trim()}}
function syncDiscovery(){["hardPart","automated","data","external","people","validation"].forEach(k=>{let e=$("d_"+k);if(e)state.discovery[k]=e.value.trim()})}
function navTo(n){if(state.step===0)syncBasic();if(state.step===1)syncDiscovery();state.step=Math.max(0,Math.min(5,Number(n)));if(!state.visited.includes(state.step))state.visited.push(state.step);if(state.step>=2)seedInv();if(state.step===5)calc();render();window.scrollTo({top:0,behavior:"smooth"})}
function nav(){$("nav").innerHTML=STEPS.map((m,i)=>`<button class="navstep ${state.step===i?"active":""} ${state.visited.includes(i)&&i!==state.step?"visited":""}" onclick="navTo(${i})"><span class="num">${state.visited.includes(i)&&i<state.step?"✓":i+1}</span><span><strong>${m[0]}</strong><small>${m[1]}</small></span></button>`).join("");let p=Math.round(state.step/5*100);$("progBar").style.width=p+"%";$("progTxt").textContent=p+"%";$("heroStep").textContent=STEPS[state.step][0];$("heroSub").textContent=STEPS[state.step][1]}
function field(l,x){return `<div class="field"><label>${l}</label>${x}</div>`}
const EXAMPLE_BANK={};
function exampleBox(id,text){EXAMPLE_BANK[id]=text;return `<div class="example-box"><div class="example-head"><b>작성 예시</b><button type="button" class="example-use" onclick="applyExample('${id}')">예시 입력</button></div><div class="example-text">${esc(text)}</div><div class="example-note">※ 예시는 참고용입니다. 자사 상황·수치·고객·기술명에 맞게 수정해 주세요.</div></div>`}
function fieldExample(l,x,id,example){return `<div class="field"><label>${l}</label>${x}${exampleBox(id,example)}</div>`}
function applyExample(id){let el=$(id),text=EXAMPLE_BANK[id];if(!el||!text)return;el.value=text;el.dispatchEvent(new Event('input',{bubbles:true}));el.dispatchEvent(new Event('change',{bubbles:true}));el.focus()}
function sel(id,a,v){return `<select id="${id}">${a.map(x=>`<option ${x===v?"selected":""}>${x}</option>`).join("")}</select>`}
function basic(){$("s0").innerHTML=`<div class="panel"><h2>1. 기업 이해</h2><p class="desc">기업규모와 기술로드맵 분야를 분리해 입력합니다. 산업분류와 운영유형을 분리한 이유는 같은 산업에서도 SW·제조·서비스형 진단문항이 달라지기 때문입니다.</p><div class="choice-row" style="margin-bottom:16px"><button class="choice ${state.entry==="no-data"?"active":""}" onclick="setEntry('no-data')">자료 없이 시작</button><button class="choice ${state.entry==="with-data"?"active":""}" onclick="setEntry('with-data')">자료와 함께 정밀진단</button><button class="choice ${state.entry==="delegate"?"active":""}" onclick="setEntry('delegate')">담당자 확인 중심</button></div><div class="grid two">${field("기업명",`<input id="companyName" value="${esc(state.company.name)}" placeholder="예: 비코닉랩">`)}${field("기업 단계",sel("companyStage",STAGES,state.company.stage))}${field("기술로드맵 기준 분야",roadmapSelect())}${field("기업 운영유형",sel("bizType",BUSINESS_TYPES,state.company.bizType))}${fieldExample("세부 업종·기술분야",`<input id="sectorDetail" value="${esc(state.company.sectorDetail)}" placeholder="예: 산업용 설비 예지보전 AI SaaS">`,"sectorDetail","산업용 제조설비 예지보전 AI SaaS / 제조 데이터 분석·이상탐지 솔루션")}${field("인원 규모",sel("companySize",SIZES,state.company.size))}${field("업력",sel("companyYears",YEARS,state.company.years))}${field("대표자의 자사 기술 이해도",sel("techKnow",["잘 알고 있음","부분적으로 알고 있음","거의 모름","담당자 확인 필요"],state.company.techKnow))}</div><div class="grid two" style="margin-top:13px">${fieldExample("주요 제품·서비스",`<textarea id="product" placeholder="제품·서비스가 무엇을 하고 어떤 결과를 제공하는지 적어주세요.">${esc(state.company.product)}</textarea>`,"product","제조설비의 진동·온도·전류 센서 데이터를 분석해 이상징후와 고장 가능성을 조기에 알려주는 AI 기반 예지보전 SaaS입니다. 설비별 상태를 대시보드로 보여주고 정비 우선순위를 추천합니다.")}${fieldExample("주요 고객·사용자",`<textarea id="customer" placeholder="누가 사용하며 어떤 문제를 해결하려는지 적어주세요.">${esc(state.company.customer)}</textarea>`,"customer","자동차·전자부품 등 중소 제조기업의 공장장, 생산기술팀, 설비보전팀이 주요 사용자입니다. 비계획 설비정지, 잦은 고장, 유지보수 비용 증가 문제를 줄이기 위해 사용합니다.")}</div><div class="notice"><b>Red Team 개선:</b> 기업단계·직원수·업력은 기술역량 점수에 직접 가산하지 않고, 기대수준과 해석문구를 조정하는 맥락변수로만 사용합니다. 규모가 크다고 기술점수가 자동으로 높아지지 않습니다.</div><h3 style="margin-top:16px">사용법 · 활용법</h3><div class="usage-guide"><div class="usage-step"><b>1. 사업언어로 입력</b><p>전문기술명을 몰라도 제품·고객·문제·현장 경험을 적으면 됩니다.</p></div><div class="usage-step"><b>2. 핵심기술 확인</b><p>자동 생성된 기술후보 중 사업성과를 좌우하는 기술만 핵심으로 지정합니다.</p></div><div class="usage-step"><b>3. 결과를 실행에 활용</b><p>진단결과를 R&D 계획, 기술문서, 지원사업 준비, 내부 회의, 멘토링에 사용합니다.</p></div></div><div class="usage-callout"><b>권장 활용:</b> 1차 자가진단 → CTO/기술담당자 확인 → 필요한 Evidence 보완 → 90일 실행 → 재진단. 처음부터 모든 자료를 준비할 필요는 없습니다.</div><div class="actions"><span></span><button class="btn primary" onclick="navTo(1)">기술 발견 시작 →</button></div></div>`}
function setEntry(v){syncBasic();state.entry=v;basic()}
const DISCOVERY_EXAMPLES={
 hardPart:"설비별로 형식이 다른 센서 데이터를 표준화하고, 고장 직전의 미세한 패턴을 학습해 오탐을 줄이는 이상탐지 알고리즘과 현장 튜닝 노하우가 가장 따라 하기 어렵습니다.",
 automated:"작업자가 엑셀과 경험으로 판단하던 설비 이상 여부를 시스템이 실시간으로 탐지하고, 위험도와 정비 우선순위까지 자동 추천합니다.",
 data:"1초 단위 진동·온도·전류 센서값, 설비 알람 로그, 고장·정비 이력, 생산량·불량률 데이터가 지속적으로 쌓입니다.",
 external:"AWS 클라우드, Anthropic/OpenAI 등 LLM API, 센서 게이트웨이 공급사, 일부 데이터 수집 모듈 외주개발에 의존합니다.",
 people:"CTO 1명, AI 개발자 2명, 백엔드 개발자 1명, 제조현장 적용을 담당하는 생산기술 PM 1명이 기술을 가장 잘 이해하고 있습니다.",
 validation:"A전자와 B부품 2개 공장에서 약 3개월간 PoC를 진행했으며, 주요 고장 유형 4종에 대해 사전 탐지 성능과 오탐률을 검증했습니다. 현재는 장기 운영 데이터가 더 필요합니다."
};
function discField(k,l,p){return fieldExample(l,`<textarea id="d_${k}" placeholder="${p}">${esc(state.discovery[k])}</textarea>`,`d_${k}`,DISCOVERY_EXAMPLES[k]||"")}
function discovery(){$("s1").innerHTML=`<div class="panel"><h2>2. Technology Discovery</h2><p class="desc">대표자가 기술명을 몰라도 답할 수 있는 질문으로 기술 후보를 역추적합니다. 각 주관식 문항에는 실제 작성 수준을 이해할 수 있도록 일관된 샘플기업 기준의 작성 예시를 넣었습니다.</p><div class="grid two">${discField("hardPart","경쟁사가 따라 하기 가장 어려운 부분","제품설계, 공정, 데이터, 알고리즘, 노하우 등")}${discField("automated","사람 대신 자동으로 판단·처리되는 부분","예측, 추천, 검사, 제어, 품질판정 등")}${discField("data","계속 쌓이는 데이터","고객, 생산, 센서, 이미지, 로그, 거래 등")}${discField("external","외부에 의존하는 부분","외주개발, LLM API, 클라우드, 장비, 공급사 등")}${discField("people","기술을 가장 잘 아는 사람","CTO, 개발자, 생산책임자, 연구소장, 외주사 등")}${discField("validation","외부에서 실제 확인된 경험","PoC, 판매, 납품, 시험, 인증, 특허 등")}</div><div class="notice"><b>작성 팁:</b> 가능한 경우 “무엇을·누가·어디서·얼마나·어떤 결과로”까지 적어주세요. 수치와 기간, 실제 고객·현장 검증 여부가 포함되면 진단 정확도가 높아집니다.</div><div class="actions"><button class="btn" onclick="navTo(0)">← 이전</button><button class="btn primary" onclick="makeInv()">기술 후보 생성 →</button></div></div>`}
function makeInv(){syncDiscovery();state.inventory=[];seedInv();if(state.discovery.hardPart)state.inventory.unshift({id:99,name:state.discovery.hardPart,type:"핵심 차별기술 후보",ownership:"자체 가능",status:"대표진술",critical:true,trl:0,confirmed:false});navTo(2)}
function inlineSel(a,v,on){return `<select onchange="${on}">${a.map(x=>`<option ${x===v?"selected":""}>${x}</option>`).join("")}</select>`}
function trlSel(v,on){return `<select onchange="${on}"><option value="0" ${!v?"selected":""}>TRL 확인필요</option><option value="2" ${v===2?"selected":""}>TRL 1~2 · 원리/개념</option><option value="4" ${v===4?"selected":""}>TRL 3~4 · PoC/실험</option><option value="6" ${v===6?"selected":""}>TRL 5~6 · 시제품/유사환경</option><option value="7" ${v===7?"selected":""}>TRL 7 · 실제환경 실증</option><option value="8" ${v===8?"selected":""}>TRL 8 · 시스템 완성</option><option value="9" ${v===9?"selected":""}>TRL 9 · 실사용/양산</option></select>`}
function inv(){seedInv();$("s2").innerHTML=`<div class="panel"><h2>3. 핵심기술 식별</h2><p class="desc">기업 전체에 TRL 하나를 붙이지 않고, 사업성과와 제품성능을 좌우하는 핵심기술별로 현재 수준을 확인합니다.</p><div class="tech-list">${state.inventory.map((t,i)=>`<div class="tech-row"><div class="tech-title"><b>${esc(t.name)}</b><small>${esc(t.type)}</small><label class="check"><input type="checkbox" ${t.critical?"checked":""} onchange="setInv(${i},'critical',this.checked)"> 핵심기술</label></div>${inlineSel(["자체","외부","혼합","확인필요","자체 가능"],t.ownership,`setInv(${i},'ownership',this.value)`)}${inlineSel(["확정","대표진술","추정","미확인"],t.status,`setInv(${i},'status',this.value)`)}${trlSel(t.trl,`setInv(${i},'trl',Number(this.value))`)}<button class="btn ${t.confirmed?"soft":""}" onclick="toggleInv(${i})">${t.confirmed?"✓ 확인":"내용 확인"}</button></div>`).join("")}</div><div class="notice"><b>핵심 원칙:</b> TRL은 기술성숙도이고, 회사규모·매출·시장성·증빙신뢰도와 분리합니다.</div><div class="actions"><button class="btn" onclick="navTo(1)">← 이전</button><button class="btn primary" onclick="navTo(3)">핵심진단 →</button></div></div>`}
function setInv(i,k,v){state.inventory[i][k]=v}function toggleInv(i){state.inventory[i].confirmed=!state.inventory[i].confirmed;inv()}
function qhtml(q,i){let a=ANCHORS[q.cat];return `<div class="q"><div class="qhead"><div class="qtitle">${i+1}. ${q.t}</div><div class="qmeta">${cname(q.cat)}${q.critical?" · 핵심":""}</div></div><div class="scale5">${a.map((x,n)=>`<button class="${state.answers[q.id]===n+1?"selected":""}" onclick="ans('${q.id}',${n+1})"><b>${n+1}</b><br>${x}</button>`).join("")}</div><div class="unknown-row"><span class="hint">현재 상태와 가장 가까운 행동·운영 수준을 선택하세요.</span><button class="unknown ${state.answers[q.id]===null?"selected":""}" onclick="ans('${q.id}',null)">? 모름·확인필요</button></div></div>`}
function diagnosis(){let qs=activeQs(),core=qs.filter(q=>q.id[0]==="q"),deep=qs.filter(q=>q.id[0]==="d");$("s3").innerHTML=`<div class="panel"><h2>4. 핵심진단</h2><p class="desc">기본 12문항으로 먼저 진단하고 필요한 경우에만 기업 운영유형에 맞는 심화문항을 추가합니다.</p><div class="choice-row" style="margin-bottom:14px"><button class="choice ${state.mode==="quick"?"active":""}" onclick="setMode('quick')">간편 · 12문항</button><button class="choice ${state.mode==="deep"?"active":""}" onclick="setMode('deep')">정밀 · ${12+deepQs().length}문항</button></div><div class="module-head"><h3>공통 핵심진단</h3><span>기술·R&D·실행·확장·전략·리스크</span></div><div class="qwrap">${core.map((q,i)=>qhtml(q,i)).join("")}</div>${state.mode==="deep"&&deep.length?`<div class="module-head"><h3>${esc(state.company.bizType)} 심화</h3><span>선택형</span></div><div class="qwrap">${deep.map((q,i)=>qhtml(q,core.length+i)).join("")}</div>`:""}<div class="notice">“모름”은 0점이 아닙니다. 미확인 상태로 남기고 근거확인·진단신뢰도에 반영합니다.</div><div class="actions"><button class="btn" onclick="navTo(2)">← 이전</button><button class="btn primary" onclick="navTo(4)">근거 확인 →</button></div></div>`}
function setMode(v){state.mode=v;diagnosis()}function ans(id,v){state.answers[id]=v;diagnosis()}
const ev=id=>evidenceLevel(state.evidence,id);
function answerLabel(q){let v=state.answers[q.id];return v===null||v===undefined?"모름·확인필요":ANCHORS[q.cat][v-1]}
function evidenceReason(q){let v=state.answers[q.id];if(v===null||v===undefined)return "모름·확인필요";if(q.critical)return "핵심판단 검증";if(v>=4)return "높은 자기평가 검증";return "선별 확인"}
function evidenceCandidates(){let qs=activeQs();return qs.filter(q=>{let v=state.answers[q.id];return q.critical||v===null||v===undefined||v>=4}).sort((a,b)=>{let av=(state.answers[a.id]===null||state.answers[a.id]===undefined)?3:(a.critical?2:1),bv=(state.answers[b.id]===null||state.answers[b.id]===undefined)?3:(b.critical?2:1);return bv-av}).slice(0,6)}
function evidence(){let qs=evidenceCandidates();$("s4").innerHTML=`<div class="panel"><h2>5. 근거 확인</h2><p class="desc">이 단계는 기술점수를 다시 매기는 단계가 아니라, <b>현재 판단을 얼마나 믿을 수 있는지 확인하는 단계</b>입니다. 최대 6개 핵심 항목만 확인합니다.</p><div class="evidence-help"><div class="mini"><strong>“모름·확인필요”의 뜻</strong><p>기술이 없다는 뜻이 아닙니다. 현재 응답자가 판단할 정보가 부족하다는 뜻입니다.</p></div><div class="mini"><strong>진단에는 어떻게 반영?</strong><p>해당 문항을 0점 처리하지 않고, 기술점수 산정에서 제외하거나 보수적으로 처리하며 진단 신뢰도를 낮춥니다.</p></div><div class="mini"><strong>그 다음에는?</strong><p>CTO·개발·생산담당자 확인 또는 최소 자료를 확보하도록 결과의 Next Best Evidence에 표시합니다.</p></div></div><div class="notice"><b>활용 예:</b> 대표가 “실제환경 검증 여부를 모름”이라고 답했다면 낮은 기술점수를 주는 대신, “기술수준 미확정 → PoC 결과·운영로그 확인 필요”로 처리합니다.</div>${qs.map((q,i)=>`<div class="ev-card"><div class="ev-head"><b>${i+1}. ${q.t}<span class="reason-chip">${evidenceReason(q)}</span></b><span>진단응답: ${answerLabel(q)}</span></div><div class="evidence">${EVIDENCE.map(e=>`<button class="epill ${Number(state.evidence[q.id]??0)===e.k?"selected":""}" onclick="setEv('${q.id}',${e.k})">${e.name}</button>`).join("")}</div><div class="anchor">${ev(q.id).desc}</div></div>`).join("")}<div class="actions"><button class="btn" onclick="navTo(3)">← 이전</button><button class="btn primary" onclick="navTo(5)">통합 진단결과 생성 →</button></div></div>`}
function setEv(id,v){state.evidence[id]=v;evidence()}


