const band=engineBand;
function topDimensions(r){const HOLD=["판단 보류",null];let arr=[["기술성숙",r.m.tech],["R&D 역량",r.m.rd],["실행준비",r.m.exec],["기술기록",r.m.evidence],["확장준비",r.m.scale],["전략정렬",r.m.strategy],["리스크대응",r.m.risk]];arr=arr.filter(x=>x[1]!==null);return{strong:arr.length?[...arr].sort((a,b)=>b[1]-a[1]).slice(0,2):[HOLD],weak:arr.length?[...arr].sort((a,b)=>a[1]-b[1]).slice(0,3):[HOLD]}}
function rootCause(area){let d={"기술성숙":"실제환경 검증기준 또는 반복 실증이 충분히 정의되지 않았을 가능성이 있습니다.","R&D 역량":"R&D 자원·실험·산출물·사업성과가 한 관리체계로 연결되지 않았을 가능성이 있습니다.","실행준비":"기술개발이 개인 책임과 경험에 의존하고 완료기준·KPI가 약할 가능성이 있습니다.","기술기록":"기술 자체보다 문서화·버전·시험·변경이력의 추적성이 부족할 가능성이 있습니다.","확장준비":"현재 규모에서는 동작하지만 고객·생산·트래픽 증가 시 병목을 검증하지 않았을 가능성이 있습니다.","전략정렬":"내부 개발과제와 시장·정부 기술로드맵·R&D/IP/인증이 분리되어 있을 가능성이 있습니다.","리스크대응":"외주·API·공급망·핵심인력·규제 의존의 중단 시나리오가 정의되지 않았을 가능성이 있습니다."};return d[area]||"추가 확인이 필요합니다."}
function actionText(area){let d={"기술성숙":["실제환경 검증기준 정의","현장 PoC 성공조건과 실패기준을 먼저 확정합니다.","기술책임자","2~4주","PoC 성공기준 100% 문서화"],"R&D 역량":["R&D 활동-성과 연결표 구축","개발과제·실험·산출물·사업성과를 한 흐름으로 관리합니다.","R&D 책임자","2주","진행 R&D 과제 100% 연결"],"실행준비":["기술과제 책임·완료기준 명확화","누가 언제 무엇을 완료하면 끝인지 기준을 정합니다.","대표/CTO","1주","P0 과제 Owner·Due Date 100% 지정"],"기술기록":["핵심기술 1페이지 정의서 작성","기술명·원리·차별점·현재수준·근거를 한 장으로 정리합니다.","기술담당","1주","핵심기술 정의서 100% 확보"],"확장준비":["Scale-up 병목 테스트","사용량·생산량 증가 시 가장 먼저 깨지는 지점을 검증합니다.","운영/생산","4~8주","병목 Top3와 한계치 확인"],"전략정렬":["공식 로드맵과 개발과제 Crosswalk","로드맵 세부분야와 내부 개발과제를 연결합니다.","대표/R&D","2주","핵심기술 Top3 매핑 완료"],"리스크대응":["외부의존도·대체경로 정의","외주·API·공급자·핵심인력 중단 시 대체경로를 준비합니다.","CTO/운영","2~3주","고위험 의존 Top5 대응책 수립"]};return d[area]||["핵심 문항 응답·담당자 확인","모름으로 남은 문항을 CTO·기술담당자와 함께 확인해 점수 산정 근거를 확보합니다.","대표/CTO","1~2주","핵심 문항 응답률 90% 이상"]}
function nextEvidence(area){let m={"기술성숙":"실제환경 PoC 결과·시험성적·운영로그","R&D 역량":"R&D 계획·실험기록·기술개발 산출물","실행준비":"담당자·일정·완료기준이 있는 기술과제표","기술기록":"핵심기술 정의서·버전이력·시험기록","확장준비":"부하테스트·양산성 검토·병목분석","전략정렬":"공식 기술로드맵 매칭근거·전략품목 Crosswalk","리스크대응":"대체공급자·백업설계·보안/규제 체크리스트"};return m[area]||"담당자 확인 응답·최소 증빙자료"}
function roadmapInput(){return {roadmapField:state.company.roadmapField,texts:[state.company.product,state.company.sectorDetail,state.discovery.hardPart,state.discovery.automated,state.discovery.data,...state.inventory.filter(x=>x.critical).map(x=>x.name)]}}
function roadmapCandidates(){return engineRoadmapCandidates(roadmapInput())}
function otherCandidates(){return otherFieldCandidates(roadmapInput())}
function itemId(m){return m.code?esc(m.code):m.itemNo?`원문 순번 ${esc(m.itemNo)}`:""}
function matchCard(m,i){const techs=(m.matchedTechs||[]).map(t=>`<li>${esc(t.name)}${t.trl?` <span class="subtle">· TRL ${esc(t.trl)}</span>`:""}${t.page?` <span class="subtle">· p.${t.page}</span>`:""}</li>`).join("");return`<div class="match-card"><div><span class="tag blue">후보 ${i+1}</span>${m.weak?' <span class="tag warn">약한 후보</span>':""} <b>${esc(m.name)}</b> <span class="subtle">${itemId(m)}</span><div class="reason">${esc(m.reason)}</div>${techs?`<ul class="match-techs">${techs}</ul>`:""}<div class="src">출처: ${esc(m.source)}</div>${m.uid?`<div data-ev-uid="${esc(m.uid)}">${evidenceHtml(m.uid)}</div>`:""}${m.trlNote?`<div class="src">※ ${esc(m.trlNote)}</div>`:""}<div class="subtle" style="margin-top:6px"><b>활용:</b> 원문 해당 쪽의 개발목표·핵심기술과 자사 기술을 대조해 Crosswalk를 작성합니다.</div></div><div class="match-score"><strong style="font-size:15px">${m.page?`p.${m.page}`:"쪽 미확인"}</strong><span>${m.evidenceGrade==="retrieved"?"원문 색인":"원문"}</span><span>내용 검증 전</span></div></div>`}
/** 핵심기술 이름만으로 선택 분야에서 찾은 품목(없으면 null) — PDF 정렬표에서 기술별로 근거 있는 후보만 연결 */
function techCandidate(t){const c=engineRoadmapCandidates({roadmapField:state.company.roadmapField,texts:[t.name]})[0];return c&&c.hits>0?c:null}
// ---- 원문 근거(Phase 3 Hybrid RAG): VITE_ROADMAP_EVIDENCE=on 일 때만 서버 함수 호출. 실패·미설정이면 표시하지 않는다.
const EVIDENCE_ON=import.meta.env.VITE_ROADMAP_EVIDENCE==="on";
let rmEvidence={key:"",items:{},status:"idle"};
function evidenceQuery(){const x=roadmapInput();return x.texts.filter(Boolean).join(" ").slice(0,600)}
function evidenceHtml(uid){const q=(rmEvidence.items[uid]||[]);return q.length?`<div class="rm-evidence">${q.map(e=>`<div class="ev-quote"><span class="tag ok">원문 근거</span> <span class="subtle">${esc(e.label)}${e.technologyName?` · ${esc(e.technologyName)}`:""}${e.trl?` · TRL ${esc(e.trl)}`:""}</span><blockquote>“${esc(e.quote)}”</blockquote><div class="src">${esc(e.citation)}</div></div>`).join("")}</div>`:""}
function evidenceNote(){return rmEvidence.status==="ok"?`<b>원문 근거</b>는 공식 로드맵 원문에서 그대로 발췌한 문장입니다(요약·생성 없음)${rmEvidence.mode==="keyword_only"?" · 현재 키워드 검색만 사용(의미 검색 꺼짐)":" · 키워드+의미 검색"}. 해당 쪽 원문으로 최종 확인하세요.`:"다음 단계(Hybrid RAG)에서 원문 문장 검색을 연결해 <b>개발목표·핵심기술 정의 원문 인용</b>까지 함께 제시합니다."}
function loadEvidence(matches){if(!EVIDENCE_ON)return;const uids=matches.map(m=>m.uid).filter(Boolean);if(!uids.length)return;const key=evidenceQuery()+"|"+uids.join(",");if(rmEvidence.key===key&&rmEvidence.status!=="error")return;rmEvidence={key,items:{},status:"loading"};fetch("/api/roadmap-evidence",{method:"POST",headers:{"content-type":"application/json"},body:JSON.stringify({query:evidenceQuery(),itemUids:uids})}).then(r=>r.ok?r.json():null).then(j=>{if(rmEvidence.key!==key)return;rmEvidence={key,items:j&&j.status==="ok"?j.items:{},status:j&&j.status==="ok"?"ok":"off",mode:j&&j.mode};document.querySelectorAll("[data-ev-uid]").forEach(el=>{el.innerHTML=evidenceHtml(el.getAttribute("data-ev-uid"))});document.querySelectorAll("[data-ev-note]").forEach(el=>{el.innerHTML=evidenceNote()});buildPrintReport()}).catch(()=>{if(rmEvidence.key===key)rmEvidence.status="error"})}
function otherFieldNote(){const o=otherCandidates();return o.length?`<div class="notice"><b>다른 분야에서 더 많이 일치한 품목:</b> ${o.map(x=>`${esc(x.field)} › <b>${esc(x.name)}</b> (${itemId(x)}${x.page?`, p.${x.page}`:""})`).join(" / ")} — '기술로드맵 기준 분야' 선택을 재검토해 보세요.</div>`:""}
